/**
 * Typed access to coverage.json, generated by scripts/build-coverage.mjs after an e2e run.
 * The glob keeps the build working when the file does not exist yet (no tests run locally).
 */
export type CoverageStatus = "passed" | "failed" | "flaky" | "skipped" | "untested";

export interface CoverageTest {
  title: string;
  file: string;
  url: string;
  status: Exclude<CoverageStatus, "untested">;
  projects: string[];
}

export interface UseCaseCoverage {
  status: CoverageStatus;
  docs: string[];
  tests: CoverageTest[];
}

interface Coverage {
  generatedAt: string | null;
  useCases: Record<string, UseCaseCoverage>;
}

const files = import.meta.glob<Coverage>("./coverage.json", { eager: true, import: "default" });

export const coverage: Coverage = files["./coverage.json"] ?? { generatedAt: null, useCases: {} };

export const STATUS_LABEL: Record<CoverageStatus, string> = {
  passed: "Teszt: sikeres",
  failed: "Teszt: hibás",
  flaky: "Teszt: instabil",
  skipped: "Teszt: kihagyva",
  untested: "Nincs teszt",
};

/** Starlight badge variants per status. */
export const STATUS_VARIANT = {
  passed: "success",
  failed: "danger",
  flaky: "caution",
  skipped: "note",
  untested: "default",
} as const satisfies Record<CoverageStatus, string>;
